"描述定制嗓音:免选音色——角色配音按项目声纹卡(voice.json 声学字段)自动拼装声线描述,旁白按项目旁白声线卡冻结描述(无卡按工单 --instructions);项目已有冻结 voiceprint 样本时自动作参考锚,同一角色逐句/逐段合成不漂音色。": "설명 기반 맞춤 음성: 음색 선택 불필요 — 캐릭터 더빙은 프로젝트 성문 카드(voice.json 음향 필드)에서 음성 설명을 자동 조립합니다; 내레이션은 내레이션 음색 카드의 고정 설명을 사용(카드가 없으면 작업 지시의 --instructions); 고정 voiceprint 샘플이 이미 있으면 자동으로 참조 앵커로 사용되어 문장/구간 단위 합성에서도 음색이 흔들리지 않습니다.",
