"代理地址仅允许本机(127.0.0.1/localhost)": "프록시 주소는 로컬(127.0.0.1/localhost)만 허용됩니다",
"说明": "설명",
"指令": "설명",
"Agent 高级设置": "Agent 고급 설정",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度": "Agent 고급 설정: 팬아웃형 Agent 동시 실행 한도, 실행/무출력 타임아웃, 대화 기억 용량, 자동 재실행 횟수 상한, 재실행 확인 대기 시간, 사고 깊이",
"重跑等待确认(秒)": "재실행 확인 대기(초)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "재실행 확인 대기는 {min}-{max} 사이의 정수(초)여야 합니다",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "재실행류 확인 팝업(「재실행할까요?」 등)의 대기 시간, 기본 60초: 카운트다운이 끝날 때까지 응답이 없으면 기본 선택지(보통 「재실행」)를 자동 적용하여 파이프라인이 사람을 기다리느라 멈추지 않습니다. 값을 키우면 판단할 시간을 더 확보할 수 있지만, 무인 상태에서는 팝업에서 그만큼 더 오래 대기합니다. Agent가 명시한 더 짧은 대기는 유효하지만 이 값을 초과할 수 없습니다. 서명류 팝업(H 게이트 수동 서명)은 카운트다운도 자동 확인도 없으므로 영향을 받지 않습니다. 전역 설정이며 저장 후 새로 발행되는 확인부터 적용됩니다.",
"⚙️ Agent 高级设置": "⚙️ Agent 고급 설정",
"重跑次数": "재실행 횟수",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Agent 자동 재실행/리롤 횟수 상한, 기본 0: 검수 채점·QA 심사·기계 검사에 불합격하면 총괄 프로듀서가 의견을 첨부해 자동으로 반려하여 다시 하게 하고, 영상/이미지 생성이 기계 검사에 미달하면 자동 리롤합니다. 같은 작업이 이 횟수에 도달해도 불합격이면 더 재시도하지 않고 사용자 판단으로 에스컬레이션합니다. 0으로 설정하면 자동 재실행을 완전히 끄고 첫 불합격 시 바로 사람에게 넘깁니다. 전역 설정이며 실행 프롬프트를 통해 모든 Agent에 주입되어 워크플로 문서에 고정된 「최대 3회」를 덮어씁니다. 저장 후 시작되는 작업부터 적용됩니다.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "재실행 횟수는 0-{max} 사이의 정수여야 합니다(0=자동 재실행 안 함)",
"轮次上限": "턴 상한",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "단일 작업 지시 내 엔진 대화 턴 수의 상한, 기본값 250: claude 및 grok 엔진에만 적용됩니다(headless의 --max-turns 파라미터, 미지정 시 무제한이므로 폭주 루프 방지를 위해 상한을 설정). codex/pi/opencode 엔진에는 해당 파라미터가 없어 영향받지 않으며, deepagents는 프레임워크 자체의 재귀 상한을 사용합니다. 상한에 도달하면 엔진이 즉시 차단되어 재개할 수 없고 — 영수증에는 종료 코드 1만 표시되며, 저장된 산출물은 남지만 검증과 영수증이 누락됩니다. 대량 작업 공정(그룹별 선별, 일괄 컷)은 한 건에 수십 그룹을 다루므로 100턴으로는 크게 부족합니다. 계속 상한에 걸리면 먼저 배치 폭을 줄이고, 그다음 이 값을 올리세요. 전역 설정이며 저장 후 시작되는 작업부터 적용됩니다.",
"轮次上限需为 {min}-{max} 的整数": "턴 상한은 {min}~{max} 사이의 정수여야 합니다",
"思考深度": "사고 깊이",
"引擎默认": "엔진 기본값",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "사고 깊이(Thinking Effort) 통합 설정, 기본값 「엔진 기본값」: 배정 시 현재 엔진별 추론 강도 파라미터로 변환됩니다 — claude → --effort, codex → model_reasoning_effort(max 없음, xhigh로 매핑), pi → --thinking, opencode → --variant(모델에 해당 단계가 없으면 무시), grok → --reasoning-effort(max 없음, xhigh로 매핑), deepagents → reasoning_effort(클라우드/OpenRouter 채널만, 로컬 모델에는 전달 안 함); kimi CLI는 해당 파라미터가 없어 영향 없음. 깊을수록 안정적이지만 느리고 token 소모가 커집니다. 「엔진 기본값」은 아무 파라미터도 전달하지 않고 각 엔진 자체 설정(~/.claude/settings.json의 effortLevel, ~/.codex/config.toml의 model_reasoning_effort 등)을 따릅니다. 전역 설정으로 모든 Agent에 적용되며 저장 후 시작되는 작업부터 유효.",
