"生成组时长与每组参考素材数量上限,须与所选视频生成模型能力匹配,按项目独立": "생성 그룹 길이 및 그룹당 참조 소재 수 상한. 선택한 영상 생성 모델의 능력에 맞춰야 하며 프로젝트별로 독립",
