"叙事节奏保存在项目的 brief.md 并注入每个 Agent 的系统提示词,节拍链约束剧本分集/分场与分镜节拍": "서사 리듬은 프로젝트의 brief.md에 저장되어 모든 Agent의 시스템 프롬프트에 주입되며, 비트 체인이 대본의 화/장면 분할과 스토리보드 템포를 제약합니다",
