"片头制作要求(留空按团队默认),可输入:\n- 时长上限(如 ≤10s)\n- 剧名:显示用标题/副标题(比如加英文名)\n- 厂标/Logo 图路径(可选,指向 refs/ 下的文件)": "인트로 제작 요구 사항(비우면 팀 기본값). 입력 가능:\n- 길이 상한(예: ≤10s)\n- 작품명: 표시용 제목/부제(예: 영문명 추가)\n- 제작사 로고 이미지 경로(선택, refs/ 아래 파일 지정)",
"片尾制作要求(留空按团队默认),可输入:\n- 时长上限(如 ≤15s)\n- 制作署名:公司名、网站 URL\n- 版权声明模板:如 © {year} {公司名}\n- 社媒/二维码(可选,指向 refs/ 下的文件)\n- 合集信息显示": "아웃트로 제작 요구 사항(비우면 팀 기본값). 입력 가능:\n- 길이 상한(예: ≤15s)\n- 제작 크레딧: 회사명, 웹사이트 URL\n- 저작권 문구 템플릿: 예: © {year} {회사명}\n- 소셜 미디어/QR 코드(선택, refs/ 아래 파일 지정)\n- 시리즈 정보 표시",
