",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", 자동 실행이 총괄 프로듀서를 깨울 때마다 메시지에 함께 첨부되어 세션이 다시 열려도 유지됩니다. 장기 제약에 적합하며 조건식으로 작성하는 것을 권장합니다(예: 「ep01-ep10 대본이 모두 완성되기 전에는 설정류 작업 지시를 배정하지 않는다」). 비워 두면 첨부하지 않습니다",
"在 ep01-ep10 剧本全部完成前,不派设定类工单": "ep01-ep10 대본이 모두 완성되기 전에는 설정류 작업 지시를 배정하지 않는다",
