"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "유휴 시간: 이 간격마다 점검하며, 파이프라인이 유휴 상태(실행 중 작업 없음, 확인 대기 항목 없음)일 때만 상태 점검 메시지를 보냅니다. 기본 5분. 임계값: 프로듀서 활성 엔진(claude/codex)의 5시간 윈도우 세션 사용량이 이 값에 도달하면 해당 회차에는 보내지 않으며, 사용량을 읽을 수 없으면 통과시킵니다. 모두 전역 설정으로 모든 프로젝트에 적용됩니다(스위치는 실행 패널 🤖 버튼, 프로젝트별 독립)",
