"(两平台账号与 Key 不互通,「接口区域」须与 Key 来源一致);克隆音色需先在平台创建;Agent 可用 --voice 按角色覆盖(传 voice_id)": "(두 플랫폼의 계정과 Key는 호환되지 않으며, “API 리전”은 Key 발급처와 일치해야 합니다). 복제 음성은 먼저 플랫폼에서 생성해야 하며, Agent는 --voice로 캐릭터별 덮어쓰기 가능(voice_id 전달)",
"MiniMax 图片生成 API(Image-01,文/图生图,参考图仅 1 张);Key 在": "MiniMax 이미지 생성 API(Image-01, 텍스트/이미지 → 이미지, 참조 이미지 1장만). Key는 ",
"MiniMax 视频生成 API(MiniMax-H3,音画同生,支持首尾帧/多参考图/参考音视频);分辨率仅 768P/2K 两档:「输出设置」的 360p/480p/720p 自动映射 768P,1080p/4k 映射 2K;时长 4-15 整数秒;Key 在": "MiniMax 영상 생성 API(MiniMax-H3, 음성·영상 동시 생성, 첫/끝 프레임·다중 참조 이미지·참조 오디오/비디오 지원). 해상도는 768P/2K 두 단계뿐: “출력 설정”의 360p/480p/720p는 768P로, 1080p/4k는 2K로 자동 매핑. 길이 4~15 정수 초. Key는 ",
"MiniMax 音乐生成 API(Music 系列);取消「强制纯音乐」时按 prompt 自动写词演唱;输出仅 .mp3/.wav;Key 在": "MiniMax 음악 생성 API(Music 시리즈). “순수 연주곡 강제”를 해제하면 prompt로 가사를 자동 작성해 노래함. 출력은 .mp3/.wav만. Key는 ",
