"云端执行(按运行秒数扣 RH 币);API Key 在": "클라우드에서 실행됩니다(실행 시간 1초당 RH 코인 차감). API Key는",
"获取;工作流须先在网页端跑通,并把 {{PROMPT}} 等占位符写入对应节点输入位(约定与本地工作流一致),再把工作流 ID 或页面链接粘贴到「添加工作流」验证;国内站与国际站账号与 Key 不互通": "에서 발급받으세요. 워크플로는 먼저 웹에서 정상 실행되는지 확인하고 {{PROMPT}} 등 플레이스홀더를 해당 노드 입력 슬롯에 작성한 뒤(로컬 워크플로와 동일한 규약), 워크플로 ID 또는 페이지 링크를 「워크플로 추가」에 붙여넣어 검증하세요. 중국 사이트와 국제 사이트의 계정과 Key는 서로 호환되지 않습니다",
"API 服务页": "API 서비스 페이지",
"诊断数据": "진단 데이터",
"诊断数据:本地记录运行事件与经验卡,手动导出诊断包提交给开发者;永不自动上传": "진단 데이터: 실행 이벤트와 경험 카드를 로컬에 기록하고, 진단 패키지를 수동으로 내보내 개발자에게 제출합니다. 자동 업로드는 없습니다",
"🩺 诊断数据": "🩺 진단 데이터",
"本地采集": "로컬 수집",
"开启时在运行结束与生成结束处按字段白名单记录结构化事件(引擎/Agent/渠道/状态/时长/脱敏后的错误模板),只写入本机 data/.videoagents/telemetry/,不含提示词、项目内容、文件路径与 API Key,永不自动上传。「导出诊断包」生成一个 zip(事件 + 环境摘要 + 下方勾选的经验卡),由你自行提交给开发者(如 GitHub issue 附件),用于改进产品。": "켜면 실행 종료·생성 종료 시 필드 화이트리스트에 따라 구조화 이벤트(엔진/Agent/채널/상태/소요 시간/마스킹된 오류 템플릿)를 기록하며, 본 기기의 data/.videoagents/telemetry/ 에만 기록합니다. 프롬프트, 프로젝트 내용, 파일 경로, API Key 는 포함되지 않으며 자동 업로드는 없습니다. \"진단 패키지 내보내기\"는 zip(이벤트 + 환경 요약 + 아래에서 선택한 경험 카드)을 생성하며, GitHub issue 첨부 등으로 직접 개발자에게 제출해 제품 개선에 사용됩니다.",
"经验卡": "경험 카드",
"任务闭环时沉淀的机制性教训(各项目 runs/<task_id>/lesson.md);默认全部不导出,逐张预览、勾选后才会进入诊断包": "작업 완료 시 축적되는 메커니즘 차원의 교훈(각 프로젝트 runs/<task_id>/lesson.md). 기본적으로 모두 내보내지 않으며, 한 장씩 미리 보고 체크한 카드만 패키지에 포함됩니다",
"包含事件": "이벤트 포함",
"诊断包中包含已采集的结构化事件文件": "수집된 구조화 이벤트 파일을 패키지에 포함합니다",
"🗑 清空事件": "🗑 이벤트 비우기",
