"清空本机已采集的事件文件?(不影响经验卡)": "로컬에 수집된 이벤트 파일을 비울까요? (경험 카드에는 영향 없음)",
"导出失败:": "내보내기 실패:",
"虚拟人像资产库": "가상 인물 자산 라이브러리",
"虚拟人像资产库 — Agentics：VideoAgents": "가상 인물 자산 라이브러리 — Agentics: VideoAgents",
"火山方舟私域虚拟人像素材库:人物形象图入库后,生成视频时自动以资产 URI 提交,规避人脸参考图审核拦截": "Volcano Ark 프라이빗 가상 인물 자산 라이브러리: 캐릭터 이미지를 등록하면 영상 생성 시 자동으로 자산 URI로 제출되어 얼굴 참조 이미지 심사 차단을 회피합니다",
"🧑‍🎨 虚拟人像资产库": "🧑‍🎨 가상 인물 자산 라이브러리",
"火山方舟私域素材库:入库的人物形象图在生成视频时以资产 URI 提交,规避人脸参考图审核拦截": "Volcano Ark 프라이빗 자산 라이브러리: 등록된 캐릭터 이미지는 영상 생성 시 자산 URI로 제출되어 얼굴 참조 심사 차단을 회피합니다",
"📋 使用前准备": "📋 사용 전 준비",
