"(私域虚拟人像素材库的前置条件)。": "(프라이빗 가상 인물 라이브러리의 전제 조건).",
"在火山引擎控制台": "Volcano Engine 콘솔의",
"API 访问密钥管理": "API 액세스 키 관리에서",
"创建并获取 Access Key / Secret Key(IAM 密钥,非 ark- 开头的方舟 API Key),填入下方并保存。": "Access Key / Secret Key(IAM 키, ark- 로 시작하는 Ark API Key가 아님)를 생성·발급받아 아래에 입력하고 저장하세요.",
"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "「활성화」를 클릭하면 아래에서 등록된 소재를 관리할 수 있습니다. 인물 미리보기의 각 이미지에 「등록」 버튼이 나타나며, 그룹 재생성 시 등록된(Active) 참조 이미지는 자동으로 자산 URI(asset://소재ID)로 제출됩니다.",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "참고: 등록은 비동기 심사입니다(Processing → Active/Failed). Active 상태의 소재만 영상 생성에 사용할 수 있습니다. 소재는 Ark 「프로젝트」로 격리되므로 아래 ProjectName은 「생성 모델」 페이지의 영상 생성용 Ark API Key 소속 프로젝트와 일치해야 합니다(기본 default).",
"🔑 密钥与开关": "🔑 키와 스위치",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "Access Key / Secret Key를 비워 두면 「⚙️ 설정 → 파일 호스팅 → Volcano TOS」에 설정된 AK/SK(또는 환경 변수 TOS_ACCESS_KEY/TOS_SECRET_KEY)를 자동 사용합니다.",
"default(须与视频生成 API Key 所属项目一致)": "default(영상 생성 API Key 소속 프로젝트와 일치해야 함)",
