"适合虚拟资产总量较小的情况，系统会在每集生成前自动清理当前虚拟资产库": "가상 인물 에셋 총량이 적은 경우에 적합합니다. 각 에피소드 생성 전에 시스템이 현재 에셋 라이브러리를 자동으로 정리합니다",
