"人物/场景/风格锚图;每一轮都会连同上一段的尾帧一起作为参考提交,保持人物一致。启动后冻结,停止后可改。": "인물/장면/스타일 앵커 이미지. 매 라운드 이전 클립의 마지막 프레임과 함께 참고로 제출되어 인물 일관성을 유지합니다. 시작 후 고정, 중지 후 수정 가능.",
