"该模型单段 {lo}–{hi} 秒;越长重播占比越低,但每段等得越久": "이 모델은 클립당 {lo}–{hi}초; 길수록 재생 반복은 줄지만 클립당 대기 시간은 늘어남",
"⚠ Kling 端点不支持参考图:首轮用第 1 张参考图作首帧,之后每轮用上一段尾帧作首帧": "⚠ Kling 엔드포인트는 참고 이미지를 받지 않음: 1라운드는 참고 이미지 1을 첫 프레임으로, 이후는 이전 클립의 마지막 프레임을 첫 프레임으로 사용",
"⚠ H3 Max Turbo 无参考端点,不支持参考图:首轮用第 1 张参考图作首帧,之后每轮用上一段尾帧作首帧;分辨率仅 480p/768p": "⚠ H3 Max Turbo는 참조 엔드포인트가 없어 참조 이미지를 받지 않습니다: 1회차는 참조 #1을 첫 프레임으로, 이후에는 이전 클립의 마지막 프레임을 첫 프레임으로 사용; 해상도 480p/768p만",
"MiniMax H3:参考图 + 尾帧合计 ≤12 件,原生音画同生": "MiniMax H3: 참고 이미지 + 마지막 프레임 합계 ≤12, 오디오·비디오 동시 생성",
"Seedance 2.0:参考图 + 尾帧合计 ≤9 张": "Seedance 2.0: 참고 이미지 + 마지막 프레임 합계 ≤9장",
"Wan 3.0:参考图 + 尾帧合计 ≤10 张,单段 2–30 秒": "Wan 3.0: 참고 이미지 + 마지막 프레임 합계 ≤10장, 클립당 2–30초",
"高级选项": "고급 옵션",
"衔接模式": "이어붙임 방식",
"参考图 + 尾帧一起作参考(默认)": "참고 이미지 + 마지막 프레임을 참고로(기본)",
"尾帧作首帧(不带参考图,衔接更平滑但人物易漂移)": "마지막 프레임을 첫 프레임으로(참고 이미지 없음; 이음새는 매끄럽지만 인물이 변하기 쉬움)",
"不衔接(文生视频:每段仅按提示词独立生成,不带参考图与尾帧)": "이어붙이지 않음(텍스트→비디오: 각 클립을 프롬프트만으로 독립 생성, 참고 이미지·마지막 프레임 없음)",
"不衔接:每段仅按提示词文生视频,参考图与尾帧都不提交,段与段之间画面不连续": "이어붙이지 않음: 각 클립은 프롬프트만으로 텍스트→비디오 생성; 참고 이미지와 마지막 프레임을 제출하지 않아 클립 간 화면이 이어지지 않음",
"导演模式(MiniMax H3 Max Director:实时连续生成,WebRTC 直推,提示词随时改)": "디렉터 모드(MiniMax H3 Max Director: 실시간 연속 생성, WebRTC 직접 전송, 프롬프트 수시 변경)",
"记忆段数": "기억 세그먼트 수",
"导演模式:保留最近多少段提示词作为上下文(1–50,默认 12)": "디렉터 모드: 최근 몇 개 세그먼트의 프롬프트를 컨텍스트로 유지할지(1–50, 기본 12)",
"MiniMax H3 Max Director(导演模式专用,实时 WebRTC)": "MiniMax H3 Max Director(디렉터 모드 전용, 실시간 WebRTC)",
"导演模式按秒计费(最少 60 秒),单会话默认最长 2 分钟(更长需向 fal 申请);关闭页面即结束": "디렉터 모드는 초 단위 과금(최소 60초), 세션당 기본 최대 2분(더 길면 fal 승인 필요), 페이지를 닫으면 종료",
"导演模式:fal 侧按约 10 秒一块连续生成,单段时长/待播上限/最多段数不适用": "디렉터 모드: fal 측에서 약 10초 단위로 연속 생성, 클립 길이/미재생 상한/최대 클립 수는 적용되지 않음",
"导演模式:MiniMax H3 Max Director 实时连续生成,视频经 WebRTC 直推本页,自带前文记忆不需尾帧衔接;参考图只取第 1 张作首帧;分辨率 480p/768p": "디렉터 모드: MiniMax H3 Max Director가 실시간으로 연속 생성, 영상은 WebRTC로 이 페이지에 직접 전송, 내장 기억으로 마지막 프레임 이어붙이기 불필요; 참고 이미지는 1번만 첫 프레임으로 사용; 해상도 480p/768p",
