"⏭ 最新": "⏭ 최신",
"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "재생 방식: 생성된 클립을 순서대로 재생; 다음 클립이 아직 없으면 최신 클립을 다시 재생하고, 도착하면 현재 클립이 끝난 뒤 이어 붙여 재생을 끊지 않습니다. 생성은 보통 재생보다 느려 '재생 반복'이 일반적이며, 클립 길이를 늘리면 반복 비율이 줄어듭니다. 대기 클립이 상한(기본 3개, 고급 옵션에서 조정)에 도달하면 생성을 멈추고 하나를 재생하면 재개합니다. 중지 후에는 전체 클립을 반복 재생합니다.",
