"场景尺寸暂按 20 × 12 m、层高 3 m 推断，请由场景建模 Agent 校准。": "장면 치수는 20 × 12 m, 높이 3 m로 추정됩니다. 장면 모델링 Agent가 보정해야 합니다.",
"几何体由布局地标推断；物体范围与高度需对照俯视图校准。": "배치 기준점에서 형상을 추정했습니다. 평면도를 기준으로 물체 범위와 높이를 보정하세요.",
"存量人物身高、文字姿态及未标时动线按规约推断；精确节拍可在白模计划中覆盖。": "기존 인물 키, 텍스트 자세 및 시간 없는 동선은 규약으로 추정됩니다. 정확한 타이밍은 블록아웃 계획에서 지정할 수 있습니다.",
