"{shot}: 运镜 {move} 需白模计划提供数值关键帧，暂按固定机位显示。": "{shot}: 카메라 이동 {move}에는 블록아웃 계획의 수치 키프레임이 필요합니다. 현재 고정 카메라로 표시합니다.",
"{shot}: 运镜幅度由 {move} 推断，请校准数值轨迹。": "{shot}: 카메라 이동 범위를 {move}에서 추정했습니다. 수치 경로를 보정하세요.",
"{shot}: 已忽略无明确原因的人物过滤，按实际机位显示在场人物。": "{shot}: 명시적 이유 없는 인물 필터를 무시하고 실제 카메라에 따라 등장인물을 표시합니다.",
"{actor}: 同场次缺少空间锚点，请补 scene_actors": "{actor}: 같은 장면에 공간 앵커가 없습니다. scene_actors를 추가하세요",
