"{actor}: 同场次在场人物，沿用 {group} 的首姿态与位置；补充走位可写 scene_actors。": "{actor}: 장면 등장인물로서 {group}의 시작 자세와 위치를 상속합니다. scene_actors에 동선을 추가할 수 있습니다.",
