"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "켜면 콘솔 입력창과 미리보기 페이지 '수정' 팝업 오른쪽에 마이크 버튼이 나타납니다. 한 번 클릭하면 녹음 시작, 다시 클릭하면 종료되며 녹음은 로컬 faster-whisper 모델로 텍스트 변환되어 커서 위치에 삽입됩니다(최대 60초, 오디오는 기기 밖으로 나가지 않으며 API 키 불필요). 인식 언어는 UI 언어를 따릅니다. 모델은 첫 사용 전 다운로드가 필요하며 클수록 정확하지만 느립니다. small로 시작하면 충분하고 Apple 실리콘은 medium 또는 large-v3-turbo도 가능합니다.",
