"出成片 = 各组当前版本归一化拼正片(cut_post)→ 转场重渲(render_transitions)→ 终版封装(finalize_episode assemble,含片头平移与 intro_offset_ok 机检)→ 后期机检。全部宿主 CLI,几分钟量级。": "최종본 출력 = 각 그룹의 현재 버전을 정규화하여 본편 결합(cut_post) → 전환 재렌더링(render_transitions) → 최종 패키징(finalize_episode assemble, 오프닝 시프트 및 intro_offset_ok 검사 포함) → 후반 자동 검사. 전부 호스트 CLI, 수 분 소요.",
"作业进行中…": "작업 진행 중…",
